source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if all(v == 8 for v in row)]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    def bands(n, seps):
        out=[]; start=0
        for s in seps:
            if start < s:
                out.append(list(range(start, s)))
            start=s+1
        if start < n:
            out.append(list(range(start,n)))
        return out
    rb, cb = bands(h, sep_rows), bands(w, sep_cols)
    out=[row[:] for row in grid]
    locations={}
    for i, rs in enumerate(rb):
        for j, cs in enumerate(cb):
            colors={grid[r][c] for r in rs for c in cs if grid[r][c] not in (0,8)}
            for color in colors:
                locations.setdefault(color, []).append((i,j))
    paint={}
    for color, points in locations.items():
        for a in range(len(points)):
            for b in range(a+1,len(points)):
                r1,c1=points[a]; r2,c2=points[b]
                if r1==r2:
                    for c in range(min(c1,c2),max(c1,c2)+1): paint[(r1,c)]=paint.get((r1,c),set())|{color}
                elif c1==c2:
                    for r in range(min(r1,r2),max(r1,r2)+1): paint[(r,c1)]=paint.get((r,c1),set())|{color}
    for (i,j), colors in paint.items():
        val=next(iter(colors)) if len(colors)==1 else sum(colors)
        for r in rb[i]:
            for c in cb[j]: out[r][c]=val
    return out
